using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OmenDataEventAction", menuName = "Data/BattleSceneSetups/Events/EventActions/OmenDataEventAction", order = 0)]
public class OmenDataEventAction : EventAction
{
	[SerializeField]
	protected OmenData omenData;

	[SerializeField]
	protected BoolActionEvent OnFadeEventsPanelWithAction;

	[SerializeField]
	protected bool enableOnOmenRewardChosenEvent;

	[SerializeField]
	[ShowIf("enableOnOmenRewardChosenEvent")]
	protected OmenDataEvent OnOmenRewardChosenEvent;

	public OmenData OmenData => omenData;

	public override void ExecuteAction(EventButton eventButton)
	{
		EventsPanel eventsPanel = eventButton.EventsPanel;
		eventsPanel.SetComingBackFromFadeAction(delegate
		{
			eventsPanel.EventButtonPressedUpdateEventDescriptionAndButtons(eventButton.ButtonIndex, instantlyUpdate: true, customEventButtonOnUpdate);
		});
		FadeEventsPanelWithAction(eventsPanel);
	}

	protected void FadeEventsPanelWithAction(EventsPanel eventsPanel)
	{
		OnFadeEventsPanelWithAction.Raise(item: false, delegate
		{
			if (enableOnOmenRewardChosenEvent)
			{
				OnOmenRewardChosenEvent.Raise(omenData);
			}
			eventsPanel.CleanEventDescriptionAndButtons();
		});
	}

	public override void InitializeActionDescriptionPanel(ActionDescriptionPanel actionDescriptionPanel)
	{
		actionDescriptionPanel.InitializeOmenInstance(omenData, upAlignment: false, downAlignmentWithoutVerticalPadding: false);
	}

	public override string GetEventButtonResultText(string resultTextID)
	{
		return Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("GainResource"), omenData.GetOmenName());
	}
}
